package io.cascadeshield.sim;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import java.util.*;
import static io.cascadeshield.sim.Models.*;
import static org.junit.jupiter.api.Assertions.*;

/** Tiny explicit unit-test fixtures, never geographic/research acquisition data. */
class SimulationEngineTest {
    private static final ObjectMapper MAPPER=new ObjectMapper().findAndRegisterModules();
    private RoadGraph graph(){List<Node> nodes=List.of(new Node(1,80.25,13.05),new Node(2,80.251,13.05),new Node(3,80.252,13.05),new Node(4,80.251,13.052));return new RoadGraph(new NetworkFile("TESTONLY","TESTONLY",List.of(13d,80d,14d,81d),nodes,List.of(edge("AB",1,2,100,nodes),edge("BC",2,3,100,nodes),edge("BD",2,4,150,nodes),edge("DC",4,3,250,nodes)),List.of(),Map.of("provenance","TEST_FIXTURE_ONLY")));}
    private Edge edge(String id,long from,long to,double length,List<Node> nodes){return new Edge(id,id,from,to,from*10+to,length,36,"TEST_FIXTURE_ONLY","residential",id,List.of(nodes.get((int)from-1).point().coordinates(),nodes.get((int)to-1).point().coordinates()),Map.of());}
    private TruckSpec spec(String id){return new TruckSpec(id,id,new Point(80.25,13.05),new Point(80.252,13.05),List.of(),36,1000,500,"Simulated driver","NORMAL",0,100);}
    private SimulationEngine engine(){SimulationEngine e=new SimulationEngine(graph(),MAPPER);e.addTruck(spec("T1"));return e;}
    private void step(SimulationEngine e,double seconds){e.control(new ControlRequest("STEP",null,seconds));}

    @Test void pauseFreezesClockAndRateChangesTimeNotGeometry(){SimulationEngine e=engine();e.control(new ControlRequest("START",null,null));e.schedulerTick();assertEquals(.1,e.raw().clockSec);e.control(new ControlRequest("PAUSE",null,null));List<Double> frozen=List.copyOf(e.truck("T1").position);for(int i=0;i<10;i++)e.schedulerTick();assertEquals(.1,e.raw().clockSec);assertEquals(frozen,e.truck("T1").position);e.control(new ControlRequest("SET_SPEED",5d,null));e.control(new ControlRequest("RESUME",null,null));e.schedulerTick();assertEquals(.6,e.raw().clockSec,1e-8);assertEquals(6,e.truck("T1").distanceTravelledM,1e-7);}
    @Test void connectedMovementHonorsDistanceAndArrival(){SimulationEngine e=engine();step(e,5);Truck t=e.truck("T1");assertEquals(50,t.offsetM,1e-7);assertEquals(List.of(80.2505,13.05),t.position);step(e,15);assertEquals("ARRIVED",t.status);assertEquals(20,t.arrivalSec);assertEquals(200,t.distanceTravelledM,1e-7);assertEquals(1,e.raw().kpis.arrived());assertEquals(0,e.raw().kpis.totalDelaySec());}
    @Test void closureBlocksOnlyAtLegalNodeAndAutomaticallyExpires(){SimulationEngine e=engine();e.addIncident(new IncidentRequest("CLOSURE","BC",1,30d,0d));step(e,15);Truck t=e.truck("T1");assertEquals("BLOCKED",t.status);assertEquals(new Point(80.251,13.05).coordinates(),t.position);assertEquals(100,t.distanceTravelledM,1e-7);step(e,25);assertEquals("ARRIVED",t.status);assertEquals(40,t.arrivalSec);assertEquals(20,e.raw().kpis.totalDelaySec());}
    @Test void severityChangesTravelTimeAndRiskStaysBounded(){SimulationEngine mild=engine(),severe=engine();mild.addIncident(new IncidentRequest("SLOWDOWN","BC",.2,1000,0d));severe.addIncident(new IncidentRequest("SLOWDOWN","BC",.8,1000,0d));assertTrue(severe.truck("T1").etaSec>mild.truck("T1").etaSec);for(Recommendation r:severe.raw().recommendations){assertTrue(r.beforeRisk()>=0&&r.beforeRisk()<=1);assertTrue(r.afterRisk()>=0&&r.afterRisk()<=1);assertEquals("RULE_BASED",r.riskSource());}}
    @Test void waitFinishesOccupiedEdgeBeforeHolding(){SimulationEngine e=engine();step(e,5);e.addIncident(new IncidentRequest("CLOSURE","BC",1,100,5d));List<Double> before=List.copyOf(e.truck("T1").position);Recommendation r=e.raw().recommendations.getFirst();e.decide(new DecisionRequest("T1","WAIT",r.id()));assertEquals(before,e.truck("T1").position);step(e,6);assertEquals("WAITING",e.truck("T1").status);assertEquals(new Point(80.251,13.05).coordinates(),e.truck("T1").position);List<Double> held=List.copyOf(e.truck("T1").position);step(e,5);assertEquals(held,e.truck("T1").position);}
    @Test void approvalReroutesFromActualPositionWithoutTeleporting(){SimulationEngine e=engine();step(e,5);e.addIncident(new IncidentRequest("CLOSURE","BC",1,900,5d));Recommendation r=e.raw().recommendations.getFirst();List<Double> before=List.copyOf(e.truck("T1").position);e.decide(new DecisionRequest("T1","REROUTE",r.id()));Truck t=e.truck("T1");assertEquals(before,t.position);assertEquals(List.of("AB","BD","DC"),t.route.edgeIds());assertEquals(50,t.offsetM,1e-7);step(e,45);assertEquals("ARRIVED",t.status);assertEquals(500,t.distanceTravelledM,1e-7);assertEquals(1,e.raw().kpis.reroutes());}
    @Test void noRerouteEveryTruckAndConsistentOptionBaseline(){SimulationEngine e=engine();e.addIncident(new IncidentRequest("SLOWDOWN","BC",.1,10,0d));assertTrue(e.raw().recommendations.isEmpty());e.removeIncident("I001");e.addIncident(new IncidentRequest("SLOWDOWN","BC",.1,1000,0d));Recommendation r=e.raw().recommendations.getFirst();assertEquals("CONTINUE",r.recommendedAction());double original=r.options().getFirst().estimatedArrivalSec();for(Option o:r.options())if(o.feasible())assertEquals(o.estimatedArrivalSec()-original,o.addedTravelSec(),1e-7);}
    @Test void replayReproducesPhysicalStateAndRecordedKpis(){SimulationEngine original=engine();step(original,5);original.addIncident(new IncidentRequest("CLOSURE","BC",1,900,5d));original.decide(new DecisionRequest("T1","REROUTE",original.raw().recommendations.getFirst().id()));step(original,45);Map<String,Object> config=MAPPER.convertValue(original.scenarioConfiguration(),Map.class);SimulationEngine replay=new SimulationEngine(graph(),MAPPER);replay.replay("Replay test",config);step(replay,50);assertEquals(original.truck("T1").position,replay.truck("T1").position);assertEquals(original.truck("T1").arrivalSec,replay.truck("T1").arrivalSec);assertEquals(original.raw().kpis,replay.raw().kpis);assertEquals(original.truck("T1").route.edgeIds(),replay.truck("T1").route.edgeIds());}
    @Test void invalidAssignmentsAndStaleApprovalsAreRejected(){SimulationEngine e=engine();TruckSpec bad=new TruckSpec("X","Bad",spec("X").start(),spec("X").destination(),List.of(),36,100,101,"D","NORMAL",0,100);assertThrows(ApiException.class,()->e.addTruck(bad));e.control(new ControlRequest("START",null,null));assertThrows(ApiException.class,()->e.updateTruck("T1",spec("T1")));e.control(new ControlRequest("PAUSE",null,null));e.addIncident(new IncidentRequest("CLOSURE","BC",1,100,0d));assertThrows(ApiException.class,()->e.decide(new DecisionRequest("T1","REROUTE","stale")));}
    @Test void overlappingSlowdownsMultiplyButRemainFinite(){SimulationEngine e=engine();e.addIncident(new IncidentRequest("SLOWDOWN","AB",1,1000,0d));e.addIncident(new IncidentRequest("SLOWDOWN","AB",1,1000,0d));assertEquals(.05,RoadGraph.speedFactor("AB",e.raw().incidents,0,false),1e-8);assertTrue(Double.isFinite(e.truck("T1").etaSec));assertTrue(e.truck("T1").risk.score()<=1);}
}
